/**
 * Të dhënat e kontaktit, bankës, rrjeteve sociale dhe SEO që përdoren në të gjithë faqen.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "site-settings".
 */
export interface SiteSetting {
  id: number;
  contactPhone?: string | null;
  contactEmail?: string | null;
  address?: string | null;
  /**
   * Numri me prefiks, p.sh. +383 44 123 456. Bosh = s’shfaqet.
   */
  whatsapp?: string | null;
  /**
   * Shfaqet në fund të faqes dhe te checkout si sinjal besimi.
   */
  businessRegistrationNumber?: string | null;
  /**
   * Një rresht për çdo ditë/periudhë, p.sh. "Hën–Pre: 09:00–17:00".
   */
  openingHours?: string | null;
  /**
   * Harta gjendet automatikisht nga adresa më lart.
   */
  showMap?: boolean | null;
  /**
   * Bosh ose 0 = "konfirmohet nga ekipi".
   */
  courierFee?: number | null;
  /**
   * Bosh = asnjëherë falas.
   */
  freeShippingThreshold?: number | null;
  /**
   * Hiq tikun për ta fshehur një opsion nga checkout.
   */
  checkoutOptions?: {
    pickupEnabled?: boolean | null;
    courierEnabled?: boolean | null;
    officePaymentEnabled?: boolean | null;
    bankTransferEnabled?: boolean | null;
    cashOnDeliveryEnabled?: boolean | null;
    /**
     * Bosh = pa minimum.
     */
    minOrderAmount?: number | null;
  };
  /**
   * Kërkon që email-i (SMTP) të jetë konfiguruar te Hostinger. Bosh = email-i i kontaktit.
   */
  orderNotificationEmail?: string | null;
  /**
   * P.sh. Alp Estetik SHPK.
   */
  legalName?: string | null;
  announcement?: {
    enabled?: boolean | null;
    /**
     * P.sh. "Dërgesë falas për porosi mbi 200€".
     */
    text?: string | null;
    linkLabel?: string | null;
    /**
     * P.sh. /promotions
     */
    linkHref?: string | null;
  };
  /**
   * Zëvendëson logon standarde lart dhe poshtë. Më mirë PNG/SVG me sfond transparent.
   */
  logo?: (number | null) | Media;
  /**
   * Hiqe tikun për ta fshehur butonin SQ/EN. Faqja kryesore mbetet në shqip.
   */
  englishEnabled?: boolean | null;
  /**
   * Standard: "Ndriço me ne!"
   */
  tagline?: string | null;
  /**
   * Standard: "Vetëm për profesionistë të licencuar…"
   */
  topBarNotice?: string | null;
  footerDescription?: string | null;
  /**
   * Kutia me mburojë në fund të çdo faqeje.
   */
  professionalNotice?: string | null;
  bankDetails?: {
    bankName?: string | null;
    accountHolder?: string | null;
    iban?: string | null;
    swift?: string | null;
  };
  socialLinks?:
    | {
        platform?: ('instagram' | 'facebook' | 'linkedin') | null;
        url?: string | null;
        id?: string | null;
      }[]
    | null;
  seoDefaultTitle?: string | null;
  seoDefaultDescription?: string | null;
  updatedAt?: string | null;
  createdAt?: string | null;
}
